    private readonly SourceWriter _writer;
    private readonly int _blockId;
    private readonly PropertyModel _model;
    private SourceWriter.BlockScope _block;

    // Shared across copies: a using local is readonly, so flags on the struct would be lost on a defensive copy.
    private readonly State _state;

    internal PropertyScope(SourceWriter writer, PropertyModel model, SourceWriter.BlockScope block)
    {
        _writer = writer;
        _model = model;
        _block = block;
        _blockId = writer.InnermostBlockId;
        _state = new State();
