        return Open(PropertyAccessorKind.Init);
    }

    // Resolves the accessor before writing so a rejected request leaves the writer untouched.
    private readonly BodyScope Open(PropertyAccessorKind kind)
    {
        PropertyAccessorModel? accessor = null;

        for (var i = 0; i < _model.Accessors.Count; i++)
        {
            if (_model.Accessors[i].Kind == kind)
            {
                accessor = _model.Accessors[i];
            }
