        if (accessor is null)
        {
            throw new ArgumentException($"'{_model.Name}' has no {kind.ToString().ToLowerInvariant()} accessor.");
        }

        RequireInnermost();
        MarkOpened(kind);

        _writer.WriteLine(SourceWriterExtensions.RenderAccessorKeyword(accessor, _model.Accessibility));

        return new BodyScope(_writer, _writer.Block());
    }

    private readonly void MarkOpened(PropertyAccessorKind kind)
    {
        var alreadyOpened = kind switch
        {
            PropertyAccessorKind.Get => _state.OpenedGet,
            PropertyAccessorKind.Set => _state.OpenedSet,
            _ => _state.OpenedInit,
